<?php session_start();require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/upload.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$scene=(int)($_GET['scene']??$_POST['scene']??0);$db=db();if(isset($_GET['delete'])){$q=$db->prepare("DELETE FROM hotspots WHERE id=? AND scene_id=?");$q->execute([(int)$_GET['delete'],$scene]);header('Location:?scene='.$scene);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$type=in_array($_POST['type']??'scene',['scene','info','image'],true)?$_POST['type']:'scene';$target=$type==='scene'?(int)($_POST['target']??0):null;$content=trim($_POST['content']??'');if($type==='image'&&($_FILES['image_file']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK)$content='/uploads/'.storeUploadedImage($_FILES['image_file'],UPLOAD_DIR);$q=$db->prepare("INSERT INTO hotspots(scene_id,target_scene_id,label,yaw,pitch,type,content) VALUES(?,?,?,?,?,?,?)");$q->execute([$scene,$target?:null,trim($_POST['label']),(float)$_POST['yaw'],(float)$_POST['pitch'],$type,$content]);header('Location:?scene='.$scene);exit;}$q=$db->prepare("SELECT s.*,p.image,p.projection,p.stereo,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.id=?");$q->execute([$scene]);$s=$q->fetch();if(!$s)exit('Scene not found');$q=$db->prepare("SELECT ts.*,p.title panorama_title FROM tour_scenes ts JOIN panoramas p ON p.id=ts.panorama_id WHERE ts.tour_id=? AND ts.id<>? ORDER BY ts.sort_order");$q->execute([$s['tour_id'],$scene]);$targets=$q->fetchAll();$q=$db->prepare("SELECT h.*,COALESCE(ts.title,p.title) target_title FROM hotspots h LEFT JOIN tour_scenes ts ON ts.id=h.target_scene_id LEFT JOIN panoramas p ON p.id=ts.panorama_id WHERE h.scene_id=?");$q->execute([$scene]);$points=$q->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"><title>Hotspot editor</title></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/tours.php?edit=<?=$s['tour_id']?>">← Сцены</a></aside><main><header><div><small>SPATIAL HOTSPOT EDITOR</small><h1><?=htmlspecialchars($s['title']?:$s['panorama_title'])?></h1></div></header><div class="hotspot-layout"><div><div id="hotspot-editor" data-image="<?=htmlspecialchars($s['image'])?>" data-projection="<?=htmlspecialchars($s['projection'])?>" data-stereo="<?=htmlspecialchars($s['stereo'])?>"></div><p class="hint">Наведите центр на нужное место и зафиксируйте точку. В VR она станет пространственным интерактивным маркером.</p><button type="button" id="capture" class="btn">⊕ ПОСТАВИТЬ ТОЧКУ В ЦЕНТРЕ</button></div><form class="editor compact hotspot-form" method="post" enctype="multipart/form-data"><input type="hidden" name="scene" value="<?=$scene?>"><label>Тип<select id="hotspot-type" name="type"><option value="scene">→ Переход в сцену</option><option value="info">ⓘ Информация</option><option value="image">▣ Фото / изображение</option></select></label><label>Подпись<input name="label" value="Перейти" required></label><label id="target-field">Целевая сцена<select name="target"><?php foreach($targets as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['title']?:$t['panorama_title'])?></option><?php endforeach;?></select></label><label id="content-field" hidden><span id="content-label">Текст</span><textarea name="content" rows="5" placeholder="Описание или URL изображения"></textarea><input id="image-file" type="file" name="image_file" accept="image/jpeg,image/png,image/webp" hidden></label><div class="form-columns"><label>Yaw<input id="yaw" type="number" step=".1" name="yaw" value="0"></label><label>Pitch<input id="pitch" type="number" step=".1" name="pitch" value="0"></label></div><button class="btn">＋ СОХРАНИТЬ HOTSPOT</button></form></div><h2>Точки сцены</h2><div class="table"><?php foreach($points as $h):?><div class="row"><span class="hotspot-kind"><?=['scene'=>'→','info'=>'ⓘ','image'=>'▣'][$h['type']]??'•'?></span><div class="grow"><b><?=htmlspecialchars($h['label'])?></b><small><?=strtoupper($h['type'])?> · yaw <?=round($h['yaw'],1)?>° / pitch <?=round($h['pitch'],1)?>°<?=$h['type']==='scene'?' → '.htmlspecialchars($h['target_title']??'scene'):''?></small></div><a class="danger" href="?scene=<?=$scene?>&delete=<?=$h['id']?>" onclick="return confirm('Удалить точку?')">×</a></div><?php endforeach;?></div></main><script type="module" src="/assets/hotspot-editor.js"></script><script>const type=document.querySelector('#hotspot-type'),target=document.querySelector('#target-field'),content=document.querySelector('#content-field'),label=document.querySelector('#content-label');function sync(){const v=type.value;target.hidden=v!=='scene';content.hidden=v==='scene';label.textContent=v==='image'?'Изображение: файл или URL':'Текст информации';document.querySelector('#image-file').hidden=v!=='image'}type.onchange=sync;sync()</script></body></html>